//! The cosigner component, linked by the runtime itself.
//!
//! `enclave:signer` is wired by hand in `signer::add_to_linker`, and the cosigner's imports are
//! generated by wit-bindgen from the vendored copy. wasmtime checks every import's name and type
//! when it links a component, so an enclave that starts on `cosigner.wasm` is one whose wiring
//! matches what the guest calls. What the calls do is `wallet`'s unit tests'.
//!
//! ```console
//! $ nix build .#cosigner
//! $ COSIGNER_WASM=result/bin/cosigner.wasm cargo test -p enclave-runtime --test cosigner -- --ignored
//! ```

use enclave_runtime::testing::Enclave;

fn guest() -> Vec<u8> {
    let path = std::env::var_os("COSIGNER_WASM")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| {
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../result/bin/cosigner.wasm")
        });
    std::fs::read(&path).unwrap_or_else(|e| {
        panic!(
            "{}: {e}; build it with `nix build .#cosigner`",
            path.display()
        )
    })
}

#[tokio::test]
#[ignore = "needs cosigner.wasm: nix build .#cosigner"]
async fn the_cosigner_links_against_the_runtime() {
    Enclave::builder(guest())
        .background_tasks()
        .start()
        .await
        .expect("the runtime links every import the cosigner makes");
}
